SELECT * FROM qna
WHERE deleted_at IS NULL

    AND status = #{status}


    AND is_private = #{isPrivate}


    AND (title ILIKE '%' || #{keyword} || '%'
         OR question_text ILIKE '%' || #{keyword} || '%')



    AND questioner_id = #{requesterId}



    AND (is_private = false

            OR questioner_id = #{requesterId}

    )

ORDER BY id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM qna
WHERE deleted_at IS NULL

    AND status = #{status}


    AND is_private = #{isPrivate}


    AND (title ILIKE '%' || #{keyword} || '%'
         OR question_text ILIKE '%' || #{keyword} || '%')



    AND questioner_id = #{requesterId}



    AND (is_private = false

            OR questioner_id = #{requesterId}

    )
